@unittest.skipUnless(tb.HAVE_GIT, "git is missing")
class DbViews(tb.UpBuild):
    """T017: directory, teams, threads and mail mirror (D15; FR-025..FR-028)."""
    def run(self, result=None):
        if self._testMethodName.startswith("test_view_"):
            return super().run(result)
        return None

    def cli(self, *args, code=0):
        r = subprocess.run([sys.executable, tb.CLI, *args], cwd=self.repo, env=self.env,
                           capture_output=True, text=True, timeout=60)
        self.assertEqual(r.returncode, code, r.stderr + r.stdout)
        return r

    def rd(self, rel):
        with open(os.path.join(self.root, rel), encoding="utf-8") as fh:
            return fh.read()

    def q(self, sql, *a):
        c = sqlite3.connect(self.db)
        try:
            return c.execute(sql, a).fetchall()
        finally:
            c.close()

    def ids(self):
        return dict(self.q("SELECT name, agent_id FROM identities"))

    def add_mail(self, sender, recipient, body, topic, status="pending", reason=None):
        sid = self.q("SELECT session_id FROM rookery_sessions WHERE name='auth-fix'")[0][0]
        c = sqlite3.connect(self.db)
        c.execute("INSERT INTO inbox(sender,recipient,body,topic,status,delivered,created_at,session_id,reason,"
                  "decided_by) VALUES(?,?,?,?,?,0,1790000000,?,?,?)",
                  (sender, recipient, body, topic, status, sid, reason, "human" if reason else None))
        c.commit()
        c.close()

    def row(self, text, name):
        return [ln for ln in text.splitlines() if ln.startswith(f"| {name} |")][0]

    def test_view_directory_index_fields(self):
        self.up(self.team, "--no-launch")
        ids = self.ids()
        ws = os.path.join(self.root, "agents", "auth-fix", "scout")
        os.makedirs(os.path.join(ws, "state"), exist_ok=True)
        with open(os.path.join(ws, "state", "turn.json"), "w") as fh:
            json.dump({"state": "busy"}, fh)
        os.makedirs(os.path.join(ws, "runs", "T-9"), exist_ok=True)
        c = sqlite3.connect(self.db)
        c.execute("INSERT INTO bindings(session_id,owner_type,owner_id,kind,value,created_at) "
                  "SELECT session_id,'identity',?, 'tmux-pane','%7','2026-01-01T00:00:00Z' "
                  "FROM identities WHERE agent_id=?", (ids["scout"], ids["scout"]))
        c.commit()
        c.close()
        self.cli("regen")
        text = self.rd("_directory/INDEX.md")
        self.assertRegex(text.splitlines()[0], r"^<!-- generated by rookery regen at .+; do not edit -->$")
        scout = self.row(text, "scout")
        for needle in ("claude", "tmux-pane:%7", "busy", "T-9", "reader", "auth-fix"):
            self.assertIn(needle, scout)
        mapper = self.row(text, "mapper")
        self.assertIn("none", mapper)
        self.assertIn("| - |", mapper)
        for f in ("ports.md", "claims.md"):
            self.assertTrue(os.path.isfile(os.path.join(self.root, "_directory", f)))

    def test_view_new_identity_after_regen(self):
        self.up(self.team, "--no-launch")
        self.cli("identity", "new", "extra", "--session", "auth-fix")
        self.assertNotIn("| extra |", self.rd("_directory/INDEX.md"))
        self.cli("regen")
        self.assertIn("| extra |", self.rd("_directory/INDEX.md"))
        out = json.loads(self.cli("regen", "--json").stdout)
        self.assertTrue(out["ok"])

    def test_view_regen_needs_root(self):
        env = {k: v for k, v in self.env.items() if k != "ROOKERY_ROOT"}
        r = subprocess.run([sys.executable, tb.CLI, "regen"], cwd=self.tmp.name, env=env,
                           capture_output=True, text=True, timeout=60)
        self.assertEqual(r.returncode, 2)
        self.assertIn("Set ROOKERY_ROOT or run from the host repo.", r.stderr)

    def test_view_team_file(self):
        self.up(self.team, "--no-launch")
        self.assertIn("Fix the token refresh race.", self.rd("_teams/auth-fix.md"))
        spec = dict(tb.TEAM, acceptance=["tests pass", "no new warnings"])
        self.write_team(spec)
        self.up(self.team, "--no-launch")
        text = self.rd("_teams/auth-fix.md")
        for needle in ("Fix the token refresh race.", "tests pass", "no new warnings", "scout", "mapper",
                       "reader", "claude"):
            self.assertIn(needle, text)
        before = text
        self.cli("regen")
        self.assertEqual(self.rd("_teams/auth-fix.md"), before)

    def test_view_threads_and_mail_no_body_and_unread_same(self):
        self.up(self.team, "--no-launch")
        ids = self.ids()
        self.add_mail(ids["scout"], ids["mapper"], "SECRET-BODY-7", "plan-review")
        self.add_mail(ids["scout"], ids["mapper"], "SECRET-BODY-7", "bad-one", "quarantined", "injection")
        self.add_mail(ids["mapper"], ids["scout"], "SECRET-BODY-7", "slow-one", "held", "loop")
        snap = "SELECT * FROM inbox ORDER BY id"
        before = self.q(snap)
        unread = self.q("SELECT COUNT(*) FROM inbox WHERE status='pending'")
        self.cli("regen")
        self.assertEqual(self.q(snap), before)  # every status, delivered and delivered_at value
        self.assertEqual(self.q("SELECT COUNT(*) FROM inbox WHERE status='pending'"), unread)
        line = [ln for ln in self.rd("_threads/INDEX.md").splitlines() if "plan-review" in ln][0]
        self.assertIn("scout", line)
        self.assertIn("mapper", line)
        self.assertIn("pending", line)
        q = self.rd("_mail/quarantine/injection/2.md")
        self.assertIn("bad-one", q)
        self.assertIn("human", q)
        h = self.rd("_mail/review/3.md")
        self.assertIn("slow-one", h)
        for d, _, fs in os.walk(self.root):
            if os.sep + "_threads" in d + os.sep or os.sep + "_mail" in d + os.sep:
                for f in fs:
                    with open(os.path.join(d, f), encoding="utf-8") as fh:
                        self.assertNotIn("SECRET-BODY-7", fh.read(), os.path.join(d, f))
        # a released row leaves the mirror
        c = sqlite3.connect(self.db)
        c.execute("UPDATE inbox SET status='pending' WHERE id=2")
        c.commit()
        c.close()
        mine = os.path.join(self.root, "_mail", "review", "my-notes.md")   # a file a person made
        with open(mine, "w") as fh:
            fh.write("my own notes\n")
        self.cli("regen")
        self.assertFalse(os.path.exists(os.path.join(self.root, "_mail/quarantine/injection/2.md")))
        self.assertTrue(os.path.exists(mine))   # regen removes only stale views that Rookery wrote

    @unittest.skipUnless(shutil.which("ste-lint"), "ste-lint missing")
    def test_view_ste_lint_passes(self):
        self.up(self.team, "--no-launch")
        ids = self.ids()
        self.add_mail(ids["scout"], ids["mapper"], "x", "plan-review")
        self.add_mail(ids["scout"], ids["mapper"], "x", "bad-one", "quarantined", "injection")
        self.add_mail(ids["mapper"], ids["scout"], "x", "slow-one", "held", "loop")
        self.cli("regen")
        glossary = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ste-glossary.txt")
        files = [os.path.join(self.root, "_teams", "auth-fix.md")]
        for d, _, fs in os.walk(self.root):
            if any(os.sep + x in d + os.sep for x in ("_directory", "_threads", "_mail")):
                files += [os.path.join(d, f) for f in fs]
        self.assertGreaterEqual(len(files), 7)
        for f in files:
            r = subprocess.run(["ste-lint", f, "--max-score", "2.0", "--glossary", glossary],
                               capture_output=True, text=True)
            self.assertEqual(r.returncode, 0, f"{f}\n{r.stdout}{r.stderr}")


